package mx.com.mesaregia.cotizaciones.application.service.impl;
import mx.com.mesaregia.cotizaciones.api.response.*; import mx.com.mesaregia.cotizaciones.application.service.CotizacionQueryService; import mx.com.mesaregia.cotizaciones.domain.entity.*; import mx.com.mesaregia.cotizaciones.domain.enums.EstadoCotizacion; import mx.com.mesaregia.cotizaciones.repository.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional(readOnly=true) public class CotizacionQueryServiceImpl implements CotizacionQueryService { private final CotizacionRepository repo; private final EventoRepository eventos; private final CotizacionSupport support; public CotizacionQueryServiceImpl(CotizacionRepository r,EventoRepository e,CotizacionSupport s){repo=r;eventos=e;support=s;}
 public PageResponse<CotizacionListItemResponse> buscar(String texto,Long cliente,EstadoCotizacion estado,LocalDate desde,LocalDate hasta,int page,int size){Specification<Cotizacion> sp=(root,q,cb)->cb.conjunction(); if(texto!=null&&!texto.isBlank())sp=sp.and((r,q,cb)->cb.like(cb.lower(r.get("folio")),"%"+texto.toLowerCase()+"%")); if(cliente!=null)sp=sp.and((r,q,cb)->cb.equal(r.get("idClienteProspectoExterno"),cliente)); if(estado!=null)sp=sp.and((r,q,cb)->cb.equal(r.get("estadoGeneral"),estado)); var now=LocalDateTime.now();var rows=repo.findAll(sp).stream().map(c->{var e=eventos.findByIdCotizacion(c.getId()).orElse(null);return new CotizacionListItemResponse(c.getId(),c.getFolio(),c.getIdClienteProspectoExterno(),c.getEstadoGeneral(),e==null?null:e.getFechaEvento(),e==null?null:e.getHoraEvento(),c.getIdVersionElegida(),c.getVersion());}).filter(x->x.fechaEvento()==null||((desde==null||!x.fechaEvento().isBefore(desde))&&(hasta==null||!x.fechaEvento().isAfter(hasta)))).filter(x->x.estado()!=EstadoCotizacion.VENCIDA||x.fechaEvento()==null||x.horaEvento()==null||!LocalDateTime.of(x.fechaEvento(),x.horaEvento()).plusDays(1).isBefore(now)).sorted(Comparator.comparing((CotizacionListItemResponse x)->x.estado()==EstadoCotizacion.VENCIDA).thenComparing(CotizacionListItemResponse::fechaEvento,Comparator.nullsLast(Comparator.naturalOrder())).thenComparing(CotizacionListItemResponse::folio)).toList(); int from=Math.min(page*size,rows.size()),to=Math.min(from+size,rows.size());return new PageResponse<>(rows.subList(from,to),page,size,rows.size(),(int)Math.ceil(rows.size()/(double)size));}
 public CotizacionResponse detalle(Long id){return support.response(support.get(id));}
}
